/* ===================== BÀI 12 · Định địa chỉ immediate/direct/indirect/indexed ===================== */
/* Bài 12 · Định địa chỉ immediate/direct/indirect/indexed (AMTS-EMB-001-M03-L04, MC51-012) — sinh bởi tools/author/mcu8051/l12.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR12=[{"label":"Ví dụ: Bốn cách nạp A","code":"; Ví dụ 1: cùng lệnh MOV A,..., bốn chế độ định địa chỉ\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     30H,#0AAH               ; chuẩn bị: ô 30H = AAH\n        MOV     R1,#30H                 ; R1 = 30H\n        MOV     A,#30H                  ; tức thời: A = số 30H\n        MOV     A,30H                   ; trực tiếp: A = nội dung ô 30H\n        MOV     A,@R1                   ; gián tiếp: ô mà R1 trỏ tới\n        MOV     A,R1                    ; thanh ghi: A = giá trị R1\n        SJMP    $\n        END\n","note":"Bốn lệnh cuối cùng nạp A từ bốn chế độ: #30H cho 30H, 30H cho AAH (ô 30H), @R1 cho AAH (ô R1 trỏ tới), R1 cho 30H. Đoán trước giá trị A trước từng lệnh; xem mã 74, E5, E7, E9.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Quên dấu #, đọc nhầm ô 30H","code":"; Ví dụ 2: muốn xuất số 30H ra P1 nhưng quên dấu #\n; Chip: AT89S52. LED P1 sáng khi chân = 0.\n        ORG     0000H\n        MOV     30H,#0FFH               ; phần khác của chương trình\n        MOV     A,30H                   ; ý định: A = 30H (quên #)\n        MOV     P1,A                    ; P1 = FFH: không LED nào sáng\n        SJMP    $\n        END\n","note":"MOV A,30H thiếu dấu # nên đọc ô 30H (FFH): P1 = FFH, không LED nào sáng. Trình dịch không báo gì vì lệnh vẫn hợp lệ; mã máy là E5 30 chứ không phải 74 30.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Rn ngắn hơn địa chỉ trực tiếp","code":"; Ví dụ 3: R5 và ô 05H là một, nhưng mã dài khác nhau\n; Chip: AT89S52, băng 0.\n        ORG     0000H\n        MOV     R5,#12H                 ; 7D 12     2 byte\n        MOV     A,R5                    ; ED        1 byte\n        MOV     B,05H                   ; 85 05 F0  3 byte, cùng ô\n        INC     05H                     ; 05 05     2 byte: R5 = 13H\n        INC     R5                      ; 0D        1 byte: R5 = 14H\n        SJMP    $\n        END\n","note":"R5 và ô 05H là một ô: MOV B,05H đọc ra 12H, INC 05H và INC R5 cùng tăng một ô thành 14H. Xem số byte: thanh ghi (ED, 0D) 1 byte, trực tiếp 2–3 byte. Mã 85 05 F0 ghi nguồn 05H trước đích F0H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Gián tiếp duyệt mảng 4 byte","code":"; Ví dụ 4: gián tiếp: một lệnh ADD A,@R0 cho cả mảng\n; Chip: AT89S52.\n        ORG     0000H\n        MOV     40H,#05H\n        MOV     41H,#10H\n        MOV     42H,#20H\n        MOV     43H,#40H\n        MOV     R0,#40H                 ; con trỏ đầu mảng\n        MOV     R2,#4\n        CLR     A\nLAP:    ADD     A,@R0                   ; cộng ô R0 trỏ tới\n        INC     R0\n        DJNZ    R2,LAP\n        MOV     44H,A                   ; tổng 75H\n        SJMP    $\n        END\n","note":"Bốn lệnh trực tiếp tạo mảng, rồi một lệnh ADD A,@R0 trong vòng lặp cộng cả 4 ô: 05H + 10H + 20H + 40H = 75H. Đoán trước: sau vòng lặp R0 bằng bao nhiêu? (44H, ô ngay sau mảng.)","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chỉ số @A+DPTR chọn mẫu LED","code":"; Ví dụ 5: định địa chỉ chỉ số: bảng mẫu LED trong CODE\n; Chip: AT89S52. LED P1 sáng khi chân = 0.\n        ORG     0000H\n        MOV     R7,#2                   ; số thứ tự mẫu\n        MOV     A,R7\n        MOV     DPTR,#MAU\n        MOVC    A,@A+DPTR               ; A = MAU[2]\n        MOV     P1,A\n        SJMP    $\nMAU:    DB      0FEH,0FCH,0F0H,00H      ; 1, 2, 4, 8 LED\n        END\n","note":"A = 2 làm chỉ số, MOVC đọc byte thứ 2 của bảng MAU (F0H): 4 LED P1.0–P1.3 sáng. Đổi số ở dòng MOV R7,#2 thành 0, 1, 3 rồi chạy lại để thấy 1, 2, 8 LED.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Quên nạp con trỏ R0","code":"; Ví dụ 6: dùng @R0 khi R0 chưa được nạp địa chỉ\n; Chip: AT89S52. Trình mô phỏng: RAM lúc đầu toàn 00H.\n        ORG     0000H\n        MOV     30H,#55H\n        MOV     A,@R0                   ; ý định đọc ô 30H, quên nạp R0\n        SJMP    $\n        END\n","note":"R0 chưa được nạp nên @R0 trỏ ô 00H (chính là R0), A = 00H thay vì 55H. Không có thông báo lỗi. Trên chip thật, ô 00H sau cấp nguồn có giá trị bất kỳ nên kết quả còn khó đoán hơn.","dev":{"led":true},"fosc":12000000}];
const sim12=makeSim51(document.getElementById("m51-l12"),{id:"s12",presets:PR12,ram:256});
makeEx51(document.getElementById("ex-l12"),"l12",[{"t":"Số, ô và ô của ô","d":"<p>Ô <code>40H<\/code> chứa một số <i>x<\/i> (từ 50H đến 7FH). Hãy ghi: ô <code>41H<\/code> = <b>con số<\/b> 40H; ô <code>42H<\/code> = <b>nội dung<\/b> ô 40H (tức <i>x<\/i>); ô <code>43H<\/code> = nội dung của ô có địa chỉ <i>x<\/i>. Ô 40H và ô <i>x<\/i> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>40H = 55H<\/code>, ô <code>55H = ABH<\/code> → <code>41H = 40H<\/code>, <code>42H = 55H<\/code>, <code>43H = ABH<\/code>.<\/p>","start":"        ORG     0000H\n; 41H = con số 40H\n; 42H = nội dung ô 40H (gọi là x)\n; 43H = nội dung ô có địa chỉ x\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":85,"0x55":171,"0x41":238,"0x42":238,"0x43":238}},"expect":{"iram":{"0x41":64,"0x42":85,"0x43":171,"0x40":85,"0x55":171}}},{"setup":{"iram":{"0x40":80,"0x50":0,"0x41":238,"0x42":238,"0x43":238}},"expect":{"iram":{"0x41":64,"0x42":80,"0x43":0,"0x40":80,"0x50":0}}},{"setup":{"iram":{"0x40":127,"0x7F":255,"0x41":238,"0x42":238,"0x43":238}},"expect":{"iram":{"0x41":64,"0x42":127,"0x43":255,"0x40":127,"0x7F":255}}},{"setup":{"iram":{"0x40":96,"0x60":60,"0x41":238,"0x42":238,"0x43":238}},"expect":{"iram":{"0x41":64,"0x42":96,"0x43":60,"0x40":96,"0x60":60}}},{"setup":{"iram":{"0x40":102,"0x66":102,"0x41":238,"0x42":238,"0x43":238}},"expect":{"iram":{"0x41":64,"0x42":102,"0x43":102,"0x40":102,"0x66":102}}},{"setup":{"iram":{"0x40":112,"0x70":18,"0x41":238,"0x42":238,"0x43":238}},"expect":{"iram":{"0x41":64,"0x42":112,"0x43":18,"0x40":112,"0x70":18}}}]},"hints":["Ba ô đích cần ba chế độ khác nhau: một hằng số (có dấu #), một địa chỉ trực tiếp, một địa chỉ gián tiếp.","MOV đích,nguồn chép thẳng giữa hai ô trực tiếp và chép hằng vào ô trực tiếp, không cần đi qua A.","Ô 43H cần “ô của ô”: giá trị trong 40H là một địa chỉ, nên phải đưa nó vào thanh ghi con trỏ trước."],"why":"#40H là con số 40H; 40H không có # là ô 40H; @R0 là ô có địa chỉ nằm trong R0. Bộ thử 4 và 6 bắt lỗi lẫn giữa con số và nội dung ô (ghi con số 40H hay x vào ô 43H); bộ thử 5 ([x] = x) là trường hợp biên mà lời giải đúng vẫn phải đạt."},{"t":"Bốn chữ số sang mã 7 đoạn","d":"<p>Bốn ô <code>40H<\/code>–<code>43H<\/code> chứa bốn chữ số 0–9. Dùng bảng <code>MA7D<\/code> có sẵn trong code mẫu (mã LED 7 đoạn anode chung) để ghi mã của từng chữ số vào bốn ô <code>50H<\/code>–<code>53H<\/code>, đúng thứ tự. Ô 40H–43H và ô 54H giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>40H..43H = 02H 00H 02H 06H<\/code> → <code>50H..53H = A4H C0H A4H 82H<\/code>.<\/p>","start":"        ORG     0000H\n; 40H..43H: 4 chữ số 0..9\n; 50H..53H: mã LED 7 đoạn của từng chữ số\n; Viết code ở đây\n        SJMP    $\nMA7D:   DB      0C0H,0F9H,0A4H,0B0H,99H ; 0..4\n        DB      92H,82H,0F8H,80H,90H    ; 5..9\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":2,"0x41":0,"0x42":2,"0x43":6,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":90}},"expect":{"iram":{"0x50":164,"0x51":192,"0x52":164,"0x53":130,"0x40":2,"0x41":0,"0x42":2,"0x43":6,"0x54":90}}},{"setup":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":90}},"expect":{"iram":{"0x50":192,"0x51":192,"0x52":192,"0x53":192,"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x54":90}}},{"setup":{"iram":{"0x40":9,"0x41":9,"0x42":9,"0x43":9,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":90}},"expect":{"iram":{"0x50":144,"0x51":144,"0x52":144,"0x53":144,"0x40":9,"0x41":9,"0x42":9,"0x43":9,"0x54":90}}},{"setup":{"iram":{"0x40":1,"0x41":2,"0x42":3,"0x43":4,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":90}},"expect":{"iram":{"0x50":249,"0x51":164,"0x52":176,"0x53":153,"0x40":1,"0x41":2,"0x42":3,"0x43":4,"0x54":90}}},{"setup":{"iram":{"0x40":8,"0x41":0,"0x42":5,"0x43":1,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":90}},"expect":{"iram":{"0x50":128,"0x51":192,"0x52":146,"0x53":249,"0x40":8,"0x41":0,"0x42":5,"0x43":1,"0x54":90}}},{"setup":{"iram":{"0x40":7,"0x41":3,"0x42":9,"0x43":0,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":90}},"expect":{"iram":{"0x50":248,"0x51":176,"0x52":144,"0x53":192,"0x40":7,"0x41":3,"0x42":9,"0x43":0,"0x54":90}}}]},"hints":["Mỗi chữ số đi qua hai chế độ: gián tiếp (đọc chữ số qua @R0) rồi chỉ số (MOVC A,@A+DPTR với DPTR = đầu bảng).","Dùng hai con trỏ R0 (nguồn 40H) và R1 (đích 50H); DPTR nạp một lần trước vòng lặp.","Thân vòng: lấy chữ số qua con trỏ nguồn, tra bảng, ghi qua con trỏ đích, tăng hai con trỏ."],"why":"Chữ số chỉ là chỉ số vào bảng: phải tra MOVC để lấy mã (bộ thử 5 bắt lỗi chép thẳng chữ số). Gián tiếp cho phép một vòng lặp đi qua 4 ô; chỉ số cho phép một lệnh MOVC tra mọi chữ số. Lời giải tham chiếu: 39 chu kỳ."},{"t":"XOR 8 byte trong 12 byte mã","d":"<p>Code mẫu tính ô <code>48H<\/code> = XOR của 8 byte <code>40H<\/code>–<code>47H<\/code> (byte kiểm tra của một gói dữ liệu) nhưng sai một chỗ và quá dài. Hãy sửa để: (1) ô 48H = 40H ⊕ 41H ⊕ … ⊕ 47H (nội dung các ô); (2) ô 40H–47H và ô 49H giữ nguyên; (3) mã dài không quá <b>12 byte<\/b> và toàn chương trình chạy không quá <b>40 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>).<\/p><p>Ví dụ: <code>40H..47H = 01H 02H 04H … 80H<\/code> → <code>48H = FFH<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,40H\n        XRL     A,41H\n        XRL     A,#42H                  ; byte ở ô 42H\n        XRL     A,43H\n        XRL     A,44H\n        XRL     A,45H\n        XRL     A,46H\n        XRL     A,47H\n        MOV     48H,A                   ; 48H = XOR của 8 byte\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":1,"0x41":2,"0x42":4,"0x43":8,"0x44":16,"0x45":32,"0x46":64,"0x47":128,"0x48":238,"0x49":90}},"expect":{"iram":{"0x40":1,"0x41":2,"0x42":4,"0x43":8,"0x44":16,"0x45":32,"0x46":64,"0x47":128,"0x48":255,"0x49":90}}},{"setup":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":0,"0x48":238,"0x49":90}},"expect":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":0,"0x48":0,"0x49":90}}},{"setup":{"iram":{"0x40":255,"0x41":255,"0x42":255,"0x43":255,"0x44":255,"0x45":255,"0x46":255,"0x47":255,"0x48":238,"0x49":90}},"expect":{"iram":{"0x40":255,"0x41":255,"0x42":255,"0x43":255,"0x44":255,"0x45":255,"0x46":255,"0x47":255,"0x48":0,"0x49":90}}},{"setup":{"iram":{"0x40":16,"0x41":32,"0x42":36,"0x43":8,"0x44":4,"0x45":2,"0x46":1,"0x47":128,"0x48":238,"0x49":90}},"expect":{"iram":{"0x40":16,"0x41":32,"0x42":36,"0x43":8,"0x44":4,"0x45":2,"0x46":1,"0x47":128,"0x48":155,"0x49":90}}},{"setup":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":90,"0x48":238,"0x49":90}},"expect":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":90,"0x48":90,"0x49":90}}},{"setup":{"iram":{"0x40":60,"0x41":165,"0x42":15,"0x43":150,"0x44":119,"0x45":24,"0x46":225,"0x47":66,"0x48":238,"0x49":90}},"expect":{"iram":{"0x40":60,"0x41":165,"0x42":15,"0x43":150,"0x44":119,"0x45":24,"0x46":225,"0x47":66,"0x48":204,"0x49":90}}}],"maxCyc":40,"maxBytes":12},"hints":["Một dòng của code mẫu XOR với con số 42H chứ không với nội dung ô 42H: dấu # đổi chế độ định địa chỉ.","Sửa xong, code mẫu dài 20 byte (mỗi XRL A,địa chỉ 2 byte). Địa chỉ trực tiếp không thay đổi được trong vòng lặp; gián tiếp thì được, và XRL A,@R0 chỉ 1 byte.","Thay các lệnh XRL địa chỉ trực tiếp bằng một vòng lặp với lệnh XRL gián tiếp 1 byte; điều kiện dừng có thể dựa vào chính con trỏ."],"why":"XRL A,#42H dùng con số 42H thay cho nội dung ô 42H (bộ thử 4: ô 42H = 24H nên kết quả lệch 66H). Bản trải đủ 8 lệnh dài 20 byte; vòng lặp gián tiếp chỉ 11 byte: 2 chu kỳ khởi tạo + 8 × 4 + 1 + 2 chu kỳ SJMP $ = 37 chu kỳ. Đổi lại chậm hơn bản trải (11 chu kỳ): chọn chế độ định địa chỉ là chọn giữa byte mã và thời gian."}]);

makeQuiz("quiz12","score12",[{"q": "Ô 30H đang chứa 77H. Lệnh MOV A,#30H làm A bằng bao nhiêu?", "o": ["77H", "00H", "Lệnh bị báo lỗi dịch", "30H"], "a": 3, "e": "Dấu # đánh dấu định địa chỉ tức thời: A nhận chính con số 30H. 77H chỉ có khi viết MOV A,30H (trực tiếp)."}, {"q": "Lệnh nào dùng định địa chỉ gián tiếp?", "o": ["MOV A,R1", "MOV A,01H", "MOV A,#01H", "MOV A,@R1"], "a": 3, "e": "Dấu @ đánh dấu gián tiếp: địa chỉ ô nằm trong R1. MOV A,R1 là định địa chỉ thanh ghi, lấy chính giá trị của R1."}, {"q": "Trình dịch kiểu Keil A51 dịch MOV A,30H thành mã máy nào?", "o": ["74 30", "E6 30", "E5 30", "85 30 E0"], "a": 2, "e": "E5 là MOV A,trực tiếp; 74 là MOV A,#dữ liệu (nạp con số). E6 là MOV A,@R0, chỉ 1 byte, không có byte địa chỉ."}, {"q": "Dòng nào làm trình dịch báo lỗi?", "o": ["MOV 30H,#00H", "MOV #30H,A", "MOV 30H,A", "MOV A,#30H"], "a": 1, "e": "Đích không thể là giá trị tức thời: không thể ghi vào một con số. Ba dòng còn lại là lệnh hợp lệ (75 30 00, F5 30, 74 30)."}, {"q": "Ở băng 0, đoạn MOV R0,#05H; MOV 05H,#09H; MOV A,@R0 chạy xong thì A bằng bao nhiêu?", "o": ["09H", "05H", "00H", "Không xác định"], "a": 0, "e": "R0 = 05H nên @R0 đọc ô 05H, vừa được ghi 09H (ô 05H cũng là R5). 05H là giá trị của R0, chỉ đúng nếu viết MOV A,R0."}]);

